  'delveUi.run.failed': 'Výprava selhala. Vracíš se k bratru Halvenovi.',
  'delveUi.npc.halven.greeting':
    'Relikviář dole se znovu posunul. Po půlnoci slyšíme skrz podlahu zpěv a akolytka Tessa přísahá, že pohřební knihy mění vlastní inkoust. Máš-li dost odvahy, {playerName}, vezmi svíci a sestup. Nevěř každému hlasu, který tam dole uslyšíš. Některé znaly tvoje jméno ještě před tvým narozením.',
  'delveUi.npc.halvenMarsh.greeting':
    'Stopa vedla na sever do bažiny, {playerName}. Pod černou vodou zpívá další relikviář a utopení mrtví odpovídají zvonům. Akolytka Edda zná tohle rákosí lépe než já, drž se blízko její lucerny. Vyber obtížnost a já podržím lano, dokud se nevrátíš.',
  'delveUi.intro.normal':
    'Schodiště je chladné a temné. Sestup pokrývají rozbité svaté kameny a ve vlhkém vzduchu visí tichý tón zvonu. Akolytka Tessa šeptá: "Relikviář by neměl být tak hluboko otevřený. Drž se u mě, {playerName}."',
  'delveUi.intro.heroic':
    'Dveře za tebou sténavě zapadnou. Jména škrábou po kameni jako nehty. Tessina svíce hoří modře. "Teď nevolají mrtvé, {playerName}. Odpovídají něčemu."',
  'delveUi.intro.litanyNormal':
    'Schody zarostlé rákosím klesají pod Slatinný most. Edda Reedhand zvedá lucernu. "Bažina si pamatuje každé jméno, které utopili, {playerName}. Zůstaň ve světle."',
  'delveUi.intro.litanyHeroic':
    'Černá voda omývá kameny náspu. Eddin plamen zeleně poblikává. "Dole znovu zpívají, {playerName}. Neodpovídej sboru."',
  'delveUi.module.reliquary_sunken_ossuary':
    'Voda prosakuje pohřebními policemi a nese starý popel ve stříbrnočerných proudech.',
  'delveUi.module.reliquary_bell_niche':
    'Desítky ručních zvonků visí v tichu, každý svázaný pohřební látkou.',
  'delveUi.module.reliquary_saintless_hall': 'Sochy s tvářemi odsekanými pečlivou nenávistí.',
  'delveUi.module.reliquary_finale': 'Pohřbený zvon jednou udeří pod tvýma nohama.',
  'delveUi.module.litany_sluice':
    'Mechem zarostlá stavidla kapou černou vodu do staré chórové krypty.',
  'delveUi.module.litany_ledger':
    'Ostrovy knih vystupují ze zaplavených kanálů a inkoust krvácí do bažiny.',
