  'classDetails.lore.warrior':
    'Válečníci jsou bojem zocelení bojovníci na blízko, kteří získávají vztek při udělování nebo přijímání poškození. Pohlcují těžké zásahy nebo drtí nepřátele mocnými zbraněmi.',
  'classDetails.lore.paladin':
    'Paladinové jsou svatí křižáci, kteří podporují spojence požehnáními, léčí zranění Hojivým světlem a chrání slabé v těžké zbroji.',
  'classDetails.lore.hunter':
    'Lovci jsou specialisté na boj z dálky, kteří bojují po boku ochočené šelmy, zasypávají nepřátele mířenými a rychlými střelami, zpomalují je bodnutím a omračující palbou a mění aspekty podle situace.',
  'classDetails.lore.rogue':
    'Tuláci jsou nenápadní zabijáci, kteří utrácejí energii a combo body za bodnutí do zad a dokončovací útoky ze stínů.',
  'classDetails.lore.priest':
    'Kněží povolávají Hojivé světlo, aby léčili a chránili spojence, zatímco stínová magie jim umožňuje vysávat život z nepřátel.',
  'classDetails.lore.shaman':
    'Šamani ovládají živly, naplňují zbraně silou, zasahují nepřátele blesky a obnovují spojence.',
  'classDetails.lore.mage':
    'Mágové ohýbají oheň, mráz a arkánní sílu, aby ničili nepřátele, vyvolávali vodu a zmrazovali hrozby na místě.',
  'classDetails.lore.warlock':
    'Černokněžníci vyvolávají démony, sesílají kletby a průběžné poškození a vysávají život z nepřátel, aby vydrželi.',
  'classDetails.lore.druid':
    'Druidové usměrňují síly přírody, léčí zranění, spoutávají nepřátele a mění se do zvířecích podob pro obranu nebo poškození.',
  'classDetails.aria':
    'Detaily třídy {className}: role {role}. Počáteční statistiky: Síla {str}, Obratnost {agi}, Výdrž {sta}, Intelekt {int}, Duch {spi}.',
  'classDetails.statBarAria': '{stat}: {value} z 25',
