  'entities.delves.collapsed_reliquary.leaveText':
    'Šplháš zpět k bratru Halvenovi u ruin relikviáře.',
  'entities.delves.drowned_litany.name': 'Utopená litanie',
  'entities.delves.drowned_litany.enterText': 'Sestupuješ do utopené svatyně na okraji močálu.',
  'entities.delves.drowned_litany.leaveText': 'Šplháš zpět k bratru Halvenovi na okraji močálu.',
  'entities.letters.ravenpost_welcome.sender': 'Havraní pošta',
  'entities.letters.ravenpost_welcome.subject': 'Havrani teď létají pro tebe',
  'entities.letters.ravenpost_welcome.body':
    'Cestovateli,\n\nHavraní pošta otevřela svá bidla po celém údolí. Hledej havraní sloupy v Eastbrooku, Fenbridge a Highwatchi: z kteréhokoli z nich můžeš posílat dopisy, mince a zboží jiným dobrodruhům a vyzvednout vše, co ti havrani přinesou.\n\nPřikládáme malou pozornost pro tvou první známku.\n\nKřídla vzhůru,\nHavraní pošta',
  'entities.letters.letter_q_wolves.sender': 'Maršál Redbrook',
  'entities.letters.letter_q_wolves.subject': 'Ohrady jsou znovu tiché',
  'entities.letters.letter_q_wolves.body':
    'Pastevci mohou pro jednou spát s oběma očima zavřenýma, a to díky tobě. Řekl jsem Havraní poště, aby ti z fondu hlídky přinesla malou odměnu.\n\nUdržuj čepel naolejovanou.\n- Maršál Redbrook',
  'entities.letters.letter_q_greyjaw.sender': 'Maršál Redbrook',
  'entities.letters.letter_q_greyjaw.subject': 'Starý Šedočelista, konečně',
  'entities.letters.letter_q_greyjaw.body':
    'Zprávy se v tak malém městě šíří rychle. Pastevci včera pili na tvé zdraví a Wilkes přísahá, že ten vlk byl velký jako vůz. Ať přehánějí: zasloužil sis to.\n\nPřijď se najíst na hlídku.\n- Maršál Redbrook',
  'entities.letters.letter_q_hollow.sender': 'Bratr Aldric',
  'entities.letters.letter_q_hollow.subject': 'Tvůj čin v temnotě',
  'entities.letters.letter_q_hollow.body':
    'Jen málokdo se kdy dozví, co bylo pohřbeno v té dutině, a ještě méně by tomu věřilo. Já to vím a nezapomenu.\n\nAť je tvá cesta osvětlena.\n- Bratr Aldric',
  'entities.itemSets.boundstone_vanguard.name': 'Předvoj spoutaného kamene',
  'entities.itemSets.boundstone_vanguard.bonus3': 'Zvyšuje rychlost útoku a sesílání o 15 %.',
